def gen(rng):
    def ipstr(x):
        return '%d.%d.%d.%d' % (x >> 24, (x >> 16) & 255, (x >> 8) & 255, x & 255)
    def mk(rules, ips):
        return '%d %d\n%s\n%s' % (len(rules), len(ips), '\n'.join(rules), '\n'.join(ips))
    base = ['ALLOW 192.168.100.0/24', 'DENY 192.168.0.5/30', 'ALLOW 192.168.1.1/22', 'ALLOW 1.0.0.0/8', 'ALLOW 2.3.4.9', 'DENY 8.8.8.8/1', 'ALLOW 5.6.7.8']
    tests = [
        mk(base, ['192.168.100.2', '192.168.0.5', '1.2.3.4', '5.6.7.8', '200.1.1.1']),
        mk(['DENY 10.0.0.0/8', 'ALLOW 0.0.0.0/0', 'ALLOW 10.1.2.3'], ['10.1.2.3', '11.0.0.1', '10.255.255.255']),
        mk(['ALLOW 255.255.255.255'], ['255.255.255.255', '255.255.255.254', '0.0.0.0']),
        mk(['DENY 0.0.0.0/0'], ['1.1.1.1']),
        mk(['ALLOW 128.0.0.0/1', 'DENY 0.0.0.0/1'], ['127.255.255.255', '128.0.0.0', '255.255.255.255', '0.0.0.0']),
        mk(['ALLOW 10.0.0.1/32', 'DENY 10.0.0.0/31', 'ALLOW 10.0.0.2/31'], ['10.0.0.0', '10.0.0.1', '10.0.0.2', '10.0.0.3', '10.0.0.4']),
    ]
    def small():
        pool = [rng.choice([0, 1, 10, 127, 128, 192, 255]) for _ in range(rng.randint(1, 3))]
        def rnd_ip():
            return (rng.choice(pool) << 24) | (rng.choice([0, 1, 168, 255]) << 16) | (rng.choice([0, 1, 100, 255]) << 8) | rng.choice([0, 1, 2, 5, 255])
        r = rng.randint(1, 6)
        rules = []
        for _ in range(r):
            x = rnd_ip()
            l = rng.choice([0, 1, 4, 8, 16, 22, 24, 30, 31, 32, None])
            spec = ipstr(x) if l is None else '%s/%d' % (ipstr(x), l)
            rules.append(rng.choice(['ALLOW', 'DENY']) + ' ' + spec)
        ips = [ipstr(rnd_ip()) for _ in range(rng.randint(1, 6))]
        return mk(rules, ips)
    for _ in range(25):
        tests.append(small())
    def big(R, Q, lens, near):
        rules, xs = [], []
        for _ in range(R):
            x = rng.getrandbits(32)
            xs.append(x)
            l = rng.choice(lens)
            spec = ipstr(x) if l == 32 and rng.random() < 0.5 else '%s/%d' % (ipstr(x), l)
            rules.append(rng.choice(['ALLOW', 'DENY']) + ' ' + spec)
        ips = []
